import{_ as t,o as r,c as i,ap as a}from"./chunks/framework.CuFS6FqL.js";const u=JSON.parse('{"title":"🔥 Incident Response","description":"How Syslifters reports, contains, and notifies on security and privacy incidents, including CRA reporting for SysReptor and reptor.","frontmatter":{"title":"🔥 Incident Response","description":"How Syslifters reports, contains, and notifies on security and privacy incidents, including CRA reporting for SysReptor and reptor."},"headers":[],"relativePath":"organization/incident-response.md","filePath":"organization/incident-response.md"}'),o={name:"organization/incident-response.md"};function n(s,e,l,d,c,p){return r(),i("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/incident-response.md for this page in Markdown format</div><h1 id="🔥-incident-response" tabindex="-1">🔥 Incident Response <a class="header-anchor" href="#🔥-incident-response" aria-label="Permalink to &quot;🔥 Incident Response&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This process covers how we report, contain, assess, and notify on suspected or confirmed security incidents, privacy incidents, and personal data breaches, including customer data we handle as a processor. It also covers Cyber Resilience Act (CRA) reporting for actively exploited vulnerabilities and severe incidents in <a href="https://docs.sysreptor.com/" target="_blank" rel="noreferrer">SysReptor</a> and <a href="https://docs.sysreptor.com/cli/getting-started/" target="_blank" rel="noreferrer">reptor</a>.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This process applies to all employees, contractors, and third parties who access or manage our information systems, networks, or data, whether stored digitally or physically. CRA manufacturer duties in this process apply to SysReptor and reptor as products with digital elements.</p><h2 id="how-to-report" tabindex="-1">How to report <a class="header-anchor" href="#how-to-report" aria-label="Permalink to &quot;How to report&quot;">​</a></h2><p>Report immediately to a director or Data Protection Officer (DPO) via Signal. Do not wait for a complete picture. Report even if you are unsure.</p><p>If Signal is unavailable, or the person you would report to is involved in the incident, send S/MIME email to <a href="mailto:team@syslifters.com" target="_blank" rel="noreferrer">team@syslifters.com</a> (<a href="/assets/team.cer" target="_blank" rel="noreferrer">cer</a> / <a href="/assets/team.pem" target="_blank" rel="noreferrer">pem</a>).</p><p>Include what you know: date and time, what happened, systems or data involved, and people involved. Incomplete reports are expected.</p><p>Examples:</p><ul><li>Lost or stolen company laptop or phone</li><li>Customer data on a personal device, in a personal cloud, or in a cloud AI tool</li><li>Unexpected access to SysReptor, SysLeaks, GitHub, or mail</li><li>Signal or email sent to the wrong person</li><li>A vulnerability report that looks like it is being exploited</li><li>A severe security incident in SysReptor or reptor, including compromise of the product, the update pipeline, or a user system via the product</li></ul><p><strong>Do not:</strong></p><ul><li>Wipe logs, reimage, or quietly fix before reporting</li><li>Discuss the incident in customer channels, public tickets, or unencrypted mail unless a director or the DPO says to</li><li>Contact affected people or the DSB on your own</li></ul><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>Directors own intake, containment, customer communication, and CRA reporting for SysReptor and reptor (SRP submissions and product-user notification). The DPO, or a director not involved in the incident, decides on DSB and individual notification. If a named person is involved, report to someone else.</p><h2 id="containment-and-assessment" tabindex="-1">Containment and assessment <a class="header-anchor" href="#containment-and-assessment" aria-label="Permalink to &quot;Containment and assessment&quot;">​</a></h2><p>Directors start containment using existing controls: lock or wipe via IKARUS/HarfangLab, revoke access, and rotate credentials. Preserve evidence (logs, Burp states, device state, access logs).</p><p>Classify in plain language:</p><ul><li>Security incident with no personal data</li><li>Personal data incident</li><li>Customer-data incident (we are the processor)</li><li>Notifiable breach</li><li>Actively exploited vulnerability in SysReptor or reptor (CRA)</li><li>Severe incident affecting the security of SysReptor or reptor (CRA)</li></ul><p>Record what is known now. Do not wait for a finished root cause.</p><h2 id="notification" tabindex="-1">Notification <a class="header-anchor" href="#notification" aria-label="Permalink to &quot;Notification&quot;">​</a></h2><ul><li><strong>Customers / controllers</strong> first when their data or systems may be affected (processor duty under GDPR Art. 33(2), plus the contract). Do not wait for a full write-up.</li><li>The Austrian <a href="https://www.dsb.gv.at/" target="_blank" rel="noreferrer">DSB</a> and individuals when Syslifters is the controller and GDPR thresholds are met. The 72-hour clock in Art. 33 runs from awareness. Notifying individuals under Art. 34 is a higher bar. A late DSB notification needs a reason.</li><li><strong>SysReptor and reptor users</strong> when CRA reporting is triggered. See <a href="#cra-reporting-sysreptor-and-reptor">CRA reporting</a>. The 24-hour CRA clock is independent of the GDPR 72-hour clock. If both apply, run both.</li></ul><p>Notifications describe the nature of the incident, data involved, likely consequences, what we did, what we ask them to do, and a named contact.</p><h2 id="cra-reporting-sysreptor-and-reptor" tabindex="-1">CRA reporting (SysReptor and reptor) <a class="header-anchor" href="#cra-reporting-sysreptor-and-reptor" aria-label="Permalink to &quot;CRA reporting (SysReptor and reptor)&quot;">​</a></h2><p>As manufacturer of SysReptor and reptor, we notify the designated CSIRT and ENISA of actively exploited vulnerabilities and severe incidents that affect the security of those products. Submit through the <a href="https://www.enisa.europa.eu/topics/product-security-and-certification/single-reporting-platform-srp" target="_blank" rel="noreferrer">single reporting platform (SRP)</a>. Use one notification record and update it as more is known.</p><p>The 24-hour clock starts when we become aware, not when we have a complete picture. Directors decide awareness and submit. Staff still report internally immediately.</p><h3 id="what-to-report" tabindex="-1">What to report <a class="header-anchor" href="#what-to-report" aria-label="Permalink to &quot;What to report&quot;">​</a></h3><p>An <strong>actively exploited vulnerability</strong> is a vulnerability for which there is reliable evidence that a malicious actor has exploited it in a system without permission of the system owner (Art. 3(42)). Good-faith testing, bug-bounty reports, and pentest findings with no evidence of malicious exploitation are not mandatory CRA notifications. Zero-days are in scope only if there is reliable evidence of exploitation.</p><p>A <strong>severe incident</strong> having an impact on the security of the product is considered severe where (Art. 14(5)):</p><ul><li>it negatively affects or is capable of negatively affecting the ability of the product to protect the availability, authenticity, integrity or confidentiality of sensitive or important data or functions, or</li><li>it has led or is capable of leading to the introduction or execution of malicious code in the product or in the network and information systems of a user of the product.</li></ul><p>Examples that <strong>count</strong>:</p><ul><li>Unauthorized access to SysReptor management systems that can expose or alter other customers&#39; projects, notes, evidence, or encryption keys</li><li>Tampering with a SysReptor release, Docker image, or PyPI <code>reptor</code> package so users could install attacker-controlled code</li><li>Compromise of the build, signing, or update pipeline in a way that could ship malicious code to users</li><li>Malicious code reaching a user&#39;s instance or workstation through SysReptor or reptor (for example a backdoored dependency that executes when reptor runs)</li></ul><p>Examples that <strong>do not count</strong> as a CRA severe incident (still report internally):</p><ul><li>A pentest, bug-bounty, or researcher finding with no incident and no evidence of malicious exploitation</li><li>A crash, performance issue, or planned downtime that does not weaken confidentiality, integrity, authenticity, or access control</li><li>A lost company laptop, mail sent to the wrong person, or a SysLeaks-only event, unless it also compromises SysReptor or reptor</li><li>A third-party CVE that cannot be exploited in SysReptor or reptor</li><li>Customer misconfiguration of a self-hosted instance, with no product security failure on our side</li></ul><p>If an actively exploited vulnerability comes from a third-party component and can be exploited in SysReptor or reptor, we notify it. If it cannot be exploited in our product, Art. 14 is not mandatory. Still report it to the component maintainer.</p><h3 id="inform-users" tabindex="-1">Inform users <a class="header-anchor" href="#inform-users" aria-label="Permalink to &quot;Inform users&quot;">​</a></h3><p>After becoming aware of an actively exploited vulnerability or a severe incident, directors inform the impacted users or, where appropriate, all users of SysReptor or reptor in a timely manner about (Art. 14(8)):</p><ul><li>The vulnerability or incident</li><li>Where necessary, any risk mitigation and corrective measures that users can deploy</li><li>Where appropriate, the same information in a structured, machine-readable format that is easily automatically processable <ul><li>GitHub provides a machine-readable format for published advisories (e.g., <a href="https://api.github.com/repos/Syslifters/sysreptor/security-advisories/GHSA-x3m3-v8pv-442r" target="_blank" rel="noreferrer">https://api.github.com/repos/Syslifters/sysreptor/security-advisories/GHSA-x3m3-v8pv-442r</a>)</li></ul></li></ul><p>Do not wait for a full write-up if users can already mitigate. If we fail to inform users in a timely manner, the notified CSIRT may inform them.</p><p>Where necessary, the designated CSIRT may request an intermediate report on relevant status updates (Art. 14(6)). Provide it.</p><h3 id="submit-to-the-csirt-and-enisa" tabindex="-1">Submit to the CSIRT and ENISA <a class="header-anchor" href="#submit-to-the-csirt-and-enisa" aria-label="Permalink to &quot;Submit to the CSIRT and ENISA&quot;">​</a></h3><p>Directors submit via the SRP. Select <a href="https://www.cert.at/" target="_blank" rel="noreferrer">CERT.at</a> as the CSIRT designated as coordinator for our main establishment in Austria. The submission is simultaneously available to ENISA.</p><p>Submitters need an <a href="https://ecas.ec.europa.eu/cas/login" target="_blank" rel="noreferrer">EU Login</a> and must register as Assigned Representatives on the SRP.</p><p>If the SRP is temporarily unavailable, wait until it is back and then submit. If immediate communication is necessary, contact CERT.at directly, then still submit through the SRP once it is available.</p><p>If dissemination would increase security risk, mark how sensitive we consider the notified information in the 72-hour notification. The receiving CSIRT can delay dissemination in particularly exceptional circumstances.</p><h4 id="actively-exploited-vulnerability" tabindex="-1">Actively exploited vulnerability <a class="header-anchor" href="#actively-exploited-vulnerability" aria-label="Permalink to &quot;Actively exploited vulnerability&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Deadline</th><th>Submit</th></tr></thead><tbody><tr><td><strong>24 hours</strong> after awareness (Art. 14(2a))</td><td>Early warning, indicating where applicable the Member States where the product has been made available</td></tr><tr><td><strong>72 hours</strong> after awareness (Art. 14(2b))</td><td>Vulnerability notification, unless already provided: general information about the affected product, general nature of the exploit and vulnerability, corrective or mitigating measures taken, measures users can take, and how sensitive we consider the notified information</td></tr><tr><td><strong>14 days after</strong> a corrective or mitigating measure is available (Art. 14(2c))</td><td>Final report, unless already provided: description of the vulnerability, severity and impact, available information about any malicious actor that has exploited or is exploiting it, and details of the security update or other corrective measures made available</td></tr></tbody></table><h4 id="severe-incident" tabindex="-1">Severe incident <a class="header-anchor" href="#severe-incident" aria-label="Permalink to &quot;Severe incident&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Deadline</th><th>Submit</th></tr></thead><tbody><tr><td><strong>24 hours</strong> after awareness (Art. 14(4a))</td><td>Early warning including at least whether the incident is suspected of being caused by unlawful or malicious acts, and where applicable the Member States where the product has been made available</td></tr><tr><td><strong>72 hours</strong> after awareness (Art. 14(4b))</td><td>Incident notification, unless already provided: general information about the nature of the incident, an initial assessment, corrective or mitigating measures taken, measures users can take, and how sensitive we consider the notified information</td></tr><tr><td><strong>One month after</strong> the 72-hour incident notification (Art. 14(4c))</td><td>Final report, unless already provided: detailed description including severity and impact, the type of threat or root cause that is likely to have triggered it, and applied and ongoing mitigation measures</td></tr></tbody></table><h2 id="records-recovery-and-review" tabindex="-1">Records, recovery, and review <a class="header-anchor" href="#records-recovery-and-review" aria-label="Permalink to &quot;Records, recovery, and review&quot;">​</a></h2><p>Directors or the DPO create a new SysReptor project at <a href="https://syslifters.sysre.pt/" target="_blank" rel="noreferrer">syslifters.sysre.pt</a> for each incident and keep the timeline, decisions, and notifications there. Include GDPR notifications, CRA SRP submissions and identifiers, and product-user notices.</p><p>Restore systems only after access is re-checked. Fix the cause, not only the symptom. Add a short post-incident note to the project.</p><p>This process is reviewed annually, after a real incident, or after a legal change.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://www.enisa.europa.eu/topics/product-security-and-certification/single-reporting-platform-srp" target="_blank" rel="noreferrer">ENISA Single Reporting Platform</a></li><li><a href="https://www.enisa.europa.eu/sites/default/files/2026-07/ENISA_CRA_SRP_Factsheet_v1.0_0.pdf" target="_blank" rel="noreferrer">ENISA CRA SRP Factsheet</a></li><li><a href="https://www.enisa.europa.eu/topics/product-security/single-reporting-platform-srp/frequently-asked-questions" target="_blank" rel="noreferrer">ENISA CRA SRP FAQs</a></li><li><a href="https://ec.europa.eu/newsroom/dae/redirection/document/122331" target="_blank" rel="noreferrer">European Commission FAQs on CRA implementation</a></li></ul><p>Last reviewed: 03/09/2026</p>',57)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
